/**
 * Hebrew language pack, node half. The empty apply gives the Loader a host-side row; the browser
 * half (lib/client.js, generated by build-client.mjs from dicts/he/*.json) ships through
 * `exports["./client"]`, exactly the shape of the shipped ui-brand-official plugin.
 *
 * WHERE THE OFFICE'S LANGUAGE LIVES. Adding a language is not selecting one: until DGO-550 nothing
 * selected one, so the interface opened in whatever `navigator.languages` asked for with the vendor's
 * `en` as the fallback (measured 2026-10-13 on the owner's phone). Under DeepSeek Harness 0.1.6 this
 * half wrote the office's language into the harness's settings document once; 0.2.x made the active
 * language the `locale` row's own config, so the office DECLARES it in the profile
 * (harness/profile/cordis.patch.yml: `- id: locale / config: { preference: he }`) and a choice in
 * Settings → שפה still wins over that declaration. Nothing is written at run time any more (EXU-64);
 * test/locale-default.test.mjs pins the declaration.
 */

/** The office's own language: what the interface opens in until somebody chooses otherwise. */
export const OFFICE_LOCALE = "he";

/** The harness's locale row, whose config carries the active language. */
export const LOCALE_ROW = "locale";

export function apply() {}
